  const code = scriptMatch[1];
  let depth = 0;
  for (let i = 0; i < code.length; i++) {
    if (code[i] === '{') depth++;
    if (code[i] === '}') depth--;
  }
  console.log('Brace balance:', depth === 0 ? 'OK' : 'UNBALANCED (' + depth + ')');

  // Count parens
  let parens = 0;
  for (let i = 0; i < code.length; i++) {
    if (code[i] === '(') parens++;
    if (code[i] === ')') parens--;
  }
